import express from 'express';
import authentication from '../middleware/authentication.js';
import characterController from '../controllers/characterController.js';
import conditionController from '../controllers/conditionController.js';
const router = express.Router();
router.get('/social/characters', characterController.getSocialCharacters);
router.get('/characters/base', characterController.getCodexCharacters);
router.get('/characters/batch', authentication.authenticate, characterController.getBatchCharacters);
router.get('/characters/:characterId', authentication.authenticate, characterController.getCharacterById);
router.get('/characters/:characterId/notes', authentication.authenticate, characterController.getCharacterNotes);
router.patch('/characters/:characterId/inventory/:inventoryId/equipment/:itemId', authentication.authenticate, characterController.toggleEquipment);
router.patch('/characters/:characterId/cart/bulk', authentication.authenticate, characterController.addBulkItems);
router.patch('/characters/:characterId/cart/:cartId', authentication.authenticate, characterController.editCart);
router.patch('/characters/:characterId/level', authentication.authenticate, characterController.updateCharacterLevel);
router.patch('/characters/:characterId/levelBonus', authentication.authenticate, characterController.selectLevelUpBonus);
router.post('/characters/:characterId/inventory/:inventoryId', authentication.authenticate, characterController.completePurchase);
router.post('/characters', authentication.authenticate, characterController.createCharacter);
router.post('/characters/base', authentication.authenticate, authentication.authenticateAdmin, characterController.createCodexCharacter);
router.post('/characters/:characterId/conditions', authentication.authenticate, characterController.createCharacterConditions);
router.post('/characters/:characterId/location', authentication.authenticate, characterController.updateCharacterLocation);
router.patch('/characters/add', authentication.authenticate, characterController.createTemplateCharacter);
router.put('/characters/:characterId', authentication.authenticate, characterController.updateCharacter);
router.put('/characters/:characterId/cart/:cartId', authentication.authenticate, characterController.clearCart);
router.delete('/characters/:characterId/conditions/:conditionId', authentication.authenticate, conditionController.deleteCharacterCondition);
router.delete('/characters/:characterId/location', authentication.authenticate, characterController.deleteLocation);
router.delete('/characters/:characterId', authentication.authenticate, characterController.deleteCharacter);
export default router;
